package cn.hydrogen.launcher;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.graphics.*;
import android.media.AudioManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import org.json.*;

/** Regression cases for the October 24 real-car reports. No vendor engines are run here. */
final class CarFixFlow {
    final Instrumentation t;final Context c;int passed,failed;MainActivity home;Activity opened;File sample;StringBuilder report=new StringBuilder();
    CarFixFlow(Instrumentation t){this.t=t;c=t.getTargetContext();}
    interface Task{void run()throws Exception;}
    void require(boolean b,String why){if(!b)throw new AssertionError(why);}
    void check(String name,Task task){try{task.run();passed++;report.append("PASS ");}catch(Throwable e){failed++;report.append("FAIL ").append(e).append(" ");}report.append(name).append('\n');}
    void main(Runnable r){Throwable[] e={null};t.runOnMainSync(()->{try{r.run();}catch(Throwable x){e[0]=x;}});t.waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
    Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
    Object invoke(Object o,String name,Class<?> type,Object value)throws Exception{Method m=o.getClass().getDeclaredMethod(name,type);m.setAccessible(true);return m.invoke(o,value);}
    View find(View v,String name){if(name.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View r=find(((ViewGroup)v).getChildAt(n),name);if(r!=null)return r;}return null;}
    void image(Activity a,String name)throws Exception{Bitmap[] bitmap={null};main(()->{View v=a.getWindow().getDecorView();bitmap[0]=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap[0]));});try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),name))){bitmap[0].compress(Bitmap.CompressFormat.PNG,100,out);}bitmap[0].recycle();}
    public void run(boolean headerOnly){Config cfg=new Config(c);Map<String,?> before=cfg.p.getAll();File old=new File(c.getFilesDir(),"wallpaper");byte[] backup=null;boolean existed=old.isFile();int originalVolume=-1;
        try{
            if(existed){ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(old)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))>=0)b.write(bytes,0,n);}backup=b.toByteArray();}
            cfg.put("autoRecoverApps",false);cfg.put("keepCompanions",false);cfg.put("weatherAuto",false);cfg.put("pageAnimation",false);
            home=(MainActivity)t.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));t.waitForIdleSync();Thread.sleep(250);
            check("app-page clock date and weather share a vertical center",()->{main(()->home.showPage(MainActivity.APPS));Thread.sleep(250);main(()->{try{TextView clock=(TextView)field(home,"clock"),date=(TextView)field(home,"date");View weather=(View)field(home,"headerWeather");int[] a=new int[2],b=new int[2],w=new int[2];clock.getLocationOnScreen(a);date.getLocationOnScreen(b);weather.getLocationOnScreen(w);float ca=a[1]+clock.getHeight()/2f,cb=b[1]+date.getHeight()/2f,cw=w[1]+weather.getHeight()/2f;require(Math.abs(ca-cb)<=2&&Math.abs(ca-cw)<=2,"centers "+ca+","+cb+","+cw);require(date.getWidth()>0&&weather.getWidth()>0,"header truncated to zero");}catch(Exception e){throw new RuntimeException(e);}});});
            image(home,"car-fixes-header-"+c.getResources().getDisplayMetrics().widthPixels+".png");
            if(!headerOnly){
                check("long-press app menu includes uninstall and opens system confirmation",()->{ResolveInfo r=new ResolveInfo();r.activityInfo=new ActivityInfo();r.activityInfo.packageName="cn.windchaser.uninstall.fixture";r.activityInfo.name="Fixture";r.activityInfo.nonLocalizedLabel="卸载测试应用";r.activityInfo.applicationInfo=new ApplicationInfo();r.activityInfo.applicationInfo.packageName=r.activityInfo.packageName;r.activityInfo.applicationInfo.nonLocalizedLabel="卸载测试应用";
                    IntentFilter filter=new IntentFilter(Intent.ACTION_DELETE);filter.addDataScheme("package");Instrumentation.ActivityMonitor monitor=t.addMonitor(filter,new Instrumentation.ActivityResult(0,null),true);
                    main(()->{AlertDialog dialog=home.appMenu(r);require(dialog.getListView().getAdapter().getCount()==3,"menu count");require(dialog.getListView().getAdapter().getItem(2).toString().contains("卸载"),"uninstall missing");dialog.getListView().performItemClick(null,2,2);dialog.dismiss();});require(monitor.getHits()==1,"system uninstall intent not sent");t.removeMonitor(monitor);
                });
                check("built-in icons cannot request uninstalling the entire launcher",()->{ResolveInfo r=Ui.apps(c).get(0);main(()->{AlertDialog dialog=home.appMenu(r);require(dialog.getListView().getAdapter().getCount()==2,"built-in uninstall exposed");dialog.dismiss();});});
                check("hierarchical city district and town name is preserved without duplicates",()->{JSONObject a=new JSONObject("{\"city\":\"安顺市\",\"county\":\"镇宁布依族苗族自治县\",\"town\":\"白马湖街道\"}");require(LocationName.json(a).equals("安顺市 镇宁布依族苗族自治县 白马湖街道"),"address incomplete");android.location.Address b=new android.location.Address(Locale.CHINA);b.setLocality("贵阳市");b.setSubAdminArea("南明区");b.setSubLocality("花果园街道");require(LocationName.address(b).equals("贵阳市 南明区 花果园街道"),"system address incomplete");require(LocationName.join("北京市","北京市","朝阳区").equals("北京市 朝阳区"),"duplicate city");});
                check("volume reads the system at startup and follows external changes",()->{AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);int previous=audio.getStreamVolume(AudioManager.STREAM_MUSIC);try{int wanted=previous==2?3:2;audio.setStreamVolume(AudioManager.STREAM_MUSIC,wanted,0);main(()->home.showPage(MainActivity.MINIMAL));Thread.sleep(200);SeekBar bar=(SeekBar)find(home.getWindow().getDecorView(),"媒体音量滑块");require(bar!=null&&bar.getProgress()==wanted,"initial volume stale");int next=wanted+1;audio.setStreamVolume(AudioManager.STREAM_MUSIC,next,0);Thread.sleep(1300);require(bar.getProgress()==next,"external volume not synchronized");}finally{audio.setStreamVolume(AudioManager.STREAM_MUSIC,previous,0);}});
                sample=new File(StorageFiles.transfer(c),"车机修复测试.png");Bitmap bm=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);bm.eraseColor(0xff39a8c2);try(OutputStream out=new FileOutputStream(sample)){bm.compress(Bitmap.CompressFormat.PNG,100,out);}bm.recycle();
                check("file opening grants a readable content URI for non-APK files",()->{Intent i=FileOpen.intent(home,sample);require("content".equals(i.getData().getScheme()),"image URI");require((i.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&i.getClipData()!=null,"read grant missing");try(InputStream in=c.getContentResolver().openInputStream(i.getData())){require(in.read()==0x89,"content not readable");}});
                check("KitKat APK intent uses compatible file URI and correct MIME",()->{File f=new File(StorageFiles.transfer(c),"车机修复测试.apk");try(FileOutputStream out=new FileOutputStream(f)){out.write(new byte[]{0x50,0x4b});}try{Intent i=FileOpen.intent(home,f);require("application/vnd.android.package-archive".equals(i.getType()),"APK MIME");require((android.os.Build.VERSION.SDK_INT<24?"file":"content").equals(i.getData().getScheme()),"platform installer URI compatibility");require(c.getPackageManager().resolveActivity(i,PackageManager.MATCH_DEFAULT_ONLY)!=null,"no system installer");}finally{f.delete();}});
                check("theme background picker opens built-in browser at the transfer folder",()->{SettingsActivity settings=(SettingsActivity)t.startActivitySync(new Intent(c,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened=settings;Instrumentation.ActivityMonitor monitor=t.addMonitor(FileCenterActivity.class.getName(),null,false);main(()->{try{Method pick=SettingsActivity.class.getDeclaredMethod("pick",String.class,int.class);pick.setAccessible(true);pick.invoke(settings,"image/*",301);}catch(Exception e){throw new RuntimeException(e);}});Activity selected=t.waitForMonitorWithTimeout(monitor,5000);t.removeMonitor(monitor);require(selected instanceof FileCenterActivity,"system picker used");opened=selected;require((Boolean)field(selected,"picker"),"picker mode not set");require(((File)field(selected,"folder")).getCanonicalFile().equals(StorageFiles.transfer(c)),"wrong initial folder");FileCenterActivity browser=(FileCenterActivity)selected;main(()->{try{invoke(browser,"open",File.class,sample);}catch(Exception e){throw new RuntimeException(e);}});for(int n=0;n<60&&!cfg.s("wallpaperKind","").equals("image");n++)Thread.sleep(100);require(cfg.s("wallpaperKind","").equals("image")&&old.isFile(),"selection did not become wallpaper");main(settings::finish);opened=null;});
                check("weather settings has themed categories and matching default background",()->{WeatherSettingsActivity settings=(WeatherSettingsActivity)t.startActivitySync(new Intent(c,WeatherSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened=settings;Thread.sleep(100);require(find(settings.getWindow().getDecorView(),"打开系统定位设置")!=null,"location action missing");image(settings,"car-fixes-weather-settings.png");main(settings::finish);opened=null;});
            }
        }catch(Throwable e){failed++;report.append("FAIL suite ").append(e).append('\n');}
        finally{if(opened!=null&&!opened.isFinishing())main(opened::finish);if(home!=null&&!home.isFinishing())main(home::finish);if(sample!=null)sample.delete();try{if(existed){try(FileOutputStream out=new FileOutputStream(old)){out.write(backup);}}else old.delete();}catch(Exception ignored){}SharedPreferences.Editor e=cfg.p.edit().clear();for(Map.Entry<String,?> v:before.entrySet()){Object o=v.getValue();if(o instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)o);else if(o instanceof Integer)e.putInt(v.getKey(),(Integer)o);else if(o instanceof Long)e.putLong(v.getKey(),(Long)o);else if(o instanceof String)e.putString(v.getKey(),(String)o);else if(o instanceof Float)e.putFloat(v.getKey(),(Float)o);}e.commit();}
        report.append("CAR_FIXES_RESULT passed=").append(passed).append(" failed=").append(failed).append('\n');Bundle out=new Bundle();out.putString("stream",report.toString());t.finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);
    }
}
